@startuml

class Airline {
  + ID : string
}

class Airport {
  + ID : string
}

class Flight {
  + ID : string
  + DepartureTime : datetime
  + ArrivalTime : datetime
}

class Aircraft {
  + Type : string
  + IsWorking : boolean
  + IsAirborne : boolean
}

class Pilot {
  + ExperienceLevel : int
}

class AeroplaneType {
  + Name : string
}

class RoleRequirement {
  + Role : string
  + RequiredCount : int
}

Airline "1" -- "*" Flight
Airline "1" -- "*" Aircraft
Flight "1" -- "1" Airport : departure
Flight "1" -- "1" Airport : arrival
Flight "1" -- "1" Pilot : captain
Flight "1" -- "1..*" Pilot : co-pilot
Flight "1" -- "1" Aircraft
Aircraft "*" -- "1" AeroplaneType
AeroplaneType "1" -- "*" RoleRequirement

@enduml

